export class ScheduleSystem{constructor(t,n){this.time=t;this.navigation=n;this.npcs=[]}register(n){this.npcs.push(n)}update(){for(const n of this.npcs){const e=this.navigation.getScheduleEntry(n.scheduleData,this.time.minutes);if(!e)continue;const k=e.start+":"+e.location;if(n.scheduleKey===k)continue;n.scheduleKey=k;const l=this.navigation.getLocation(e.location);if(l)n.setDestination({x:l.x,y:l.y},e.activity)}}}
